async ({ workspace: { read, edit }, git: { add, commit, push }, shell: { execFile, exec } }) => {
  const r = await read("docs/extensions.md", { format: "raw" });
  await edit("docs/extensions.md", { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace("Use only the inputs: pi-action logs from the stored entries, also when a run continues a thread.", "Use only the inputs: pi-action calls the functions for the stored entries of the conversation, not while the tool runs.") }] });
  const t = await exec("npx vitest run src/docs.test.ts 2>&1 | grep -E 'Tests|FAIL'");
  await add(["-A", "src", "docs", "CONTRIBUTING.md"]);
  const c = await commit(["-m", "feat: let tools say how the workflow log shows their calls", "-m", "A tool of a pi-durable extension can have an optional `present` field:\n`call(args)` returns the 🔧 line and the details of the arguments, and\n`result(args, result)` the ↳ summary and the details of the output.\npi-action checks what they return, keeps its limits, and falls back to the\ngeneric form, with one warning, when they fail. pi-durable is unchanged:\nthe field is read as unknown.", "-m", "Refs #80"]);
  const p = await push(["-u", "origin", "feat/80-tool-presentation"]);
  return { t: t.stdout, c: c.stdout.slice(-200), p: p.code, perr: p.code ? p.stderr : "" };
}
